'use client'

import * as React from 'react'
import { FluidCountdown } from '@/components/spaceui/fluid-countdown'

const PRESETS = [
  { label: 'Sprint', duration: 30 },
  { label: 'Focus', duration: 300 },
  { label: 'Pomodoro', duration: 1500 },
]

export default function Demo() {
  const [selectedPreset, setSelectedPreset] = React.useState(PRESETS[0])

  return (
    <div className="flex min-h-[480px] w-full flex-col items-center justify-center gap-6 p-6 bg-background text-foreground">
      {/* Preset Switcher Pills */}
      <div className="flex items-center gap-2 rounded-2xl border border-border/60 bg-muted/40 p-1.5 backdrop-blur-md">
        {PRESETS.map((preset) => {
          const active = selectedPreset.label === preset.label
          return (
            <button
              key={preset.label}
              type="button"
              onClick={() => setSelectedPreset(preset)}
              className={`rounded-xl px-3.5 py-1.5 text-xs font-semibold transition-all cursor-pointer ${
                active
                  ? 'bg-primary text-primary-foreground shadow-xs'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted/70'
              }`}
            >
              {preset.label}
            </button>
          )
        })}
      </div>

      <FluidCountdown
        key={selectedPreset.duration}
        duration={selectedPreset.duration}
        autoStart
        loop
        label={`Space UI ${selectedPreset.label}`}
        accentColor="oklch(0.65 0.24 265)"
      />
    </div>
  )
}
